-- Generated by `pikku db generate` from the '@pikku/extension-spindle' addon.
-- Re-run the command after changing that source.

-- Spindle's library inside Studio. One owner, so no org column; every table is
-- spindle_-prefixed so it cannot collide with the app or another addon.

create table "spindle_asset" (
  "asset_id" text not null primary key,
  "catalogue_number" integer not null unique,
  "title" text not null,
  "file_name" text not null,
  "mime_type" text not null,
  "kind" text not null check ("kind" in ('document', 'text', 'audio', 'video', 'image')),
  "size_bytes" integer not null,
  "content_key" text not null,
  "batch_id" text,
  "status" text not null default 'uploaded' check ("status" in ('uploaded', 'extracting', 'extracted', 'failed')),
  "created_at" text not null default (datetime('now')),
  "updated_at" text not null default (datetime('now'))
);

create table "spindle_extraction" (
  "extraction_id" text not null primary key,
  "asset_id" text not null references "spindle_asset" ("asset_id") on delete cascade,
  "step" text not null,
  "status" text not null default 'running' check ("status" in ('running', 'done', 'failed')),
  "result" text,
  "error" text,
  "detail" text,
  "started_at" text not null default (datetime('now')),
  "finished_at" text,
  unique ("asset_id", "step")
);

create table "spindle_knowledge_base" (
  "kb_id" text not null primary key,
  "name" text not null unique,
  "description" text not null,
  "replacing_since" text,
  "created_at" text not null default (datetime('now')),
  "updated_at" text not null default (datetime('now'))
);

create table "spindle_placement" (
  "placement_id" text not null primary key,
  "kb_id" text not null references "spindle_knowledge_base" ("kb_id") on delete cascade,
  "asset_id" text not null references "spindle_asset" ("asset_id") on delete cascade,
  "source" text not null check ("source" in ('workflow', 'member')),
  "state" text not null default 'placed' check ("state" in ('placed', 'removed')),
  "confidence" real,
  "reason" text,
  "created_at" text not null default (datetime('now')),
  "updated_at" text not null default (datetime('now')),
  unique ("kb_id", "asset_id")
);

create index "spindle_placement_asset_idx" on "spindle_placement" ("asset_id");

-- Proposed knowledge bases for assets that fit none. A proposal never creates
-- anything by itself: the owner accepts, redirects or dismisses it.

create table "spindle_proposal" (
  "proposal_id" text not null primary key,
  "name" text not null,
  "description" text not null,
  "reason" text not null,
  "state" text not null default 'open' check ("state" in ('open', 'accepted', 'redirected', 'dismissed')),
  "kb_id" text references "spindle_knowledge_base" ("kb_id") on delete set null,
  "decided_at" text,
  "created_at" text not null default (datetime('now')),
  "updated_at" text not null default (datetime('now'))
);

create index "spindle_proposal_state_idx" on "spindle_proposal" ("state");

-- Kept after a dismissal: that is how the same grouping is recognised and not proposed again.
create table "spindle_proposal_asset" (
  "proposal_id" text not null references "spindle_proposal" ("proposal_id") on delete cascade,
  "asset_id" text not null references "spindle_asset" ("asset_id") on delete cascade,
  "fit" real not null,
  "note" text not null,
  primary key ("proposal_id", "asset_id")
);

create index "spindle_proposal_asset_asset_idx" on "spindle_proposal_asset" ("asset_id");

-- Passages: what each asset yielded, cut into searchable pieces with the place they
-- came from. Derived: indexing rewrites an asset's passages, and they go with the asset.
-- Embeddings are stored as float32 blobs and ranked in code, so no vector extension is needed.

create table "spindle_passage" (
  "passage_id" text not null primary key,
  "asset_id" text not null references "spindle_asset" ("asset_id") on delete cascade,
  "source" text not null check ("source" in ('summary', 'page', 'speech', 'frame')),
  "ord" integer not null,
  "page" integer,
  "start_seconds" real,
  "end_seconds" real,
  "frame_at" real,
  "text" text not null,
  "original" text,
  "embedding" blob not null,
  "model" text not null,
  "created_at" text not null default (datetime('now'))
);

create index "spindle_passage_asset_idx" on "spindle_passage" ("asset_id", "ord");

-- Keyword side of the search, English stemming so "glazes" finds "glaze".
create virtual table "spindle_passage_fts" using fts5(
  "text",
  content = 'spindle_passage',
  content_rowid = 'rowid',
  tokenize = 'porter unicode61'
);

create trigger "spindle_passage_ai" after insert on "spindle_passage" begin
  insert into "spindle_passage_fts" (rowid, "text") values (new.rowid, new."text");
end;

create trigger "spindle_passage_ad" after delete on "spindle_passage" begin
  insert into "spindle_passage_fts" ("spindle_passage_fts", rowid, "text") values ('delete', old.rowid, old."text");
end;
